-- Frozen brood database of schema version 58 (#274): DDL and rows written by
-- store.Open and the store API of that version. Generated by
-- go test ./brood/store -run TestSchemaFixtureMatchesCurrentSchema -update-schema-fixture
-- while schemaVersion was this version. Never edit it by hand.
BEGIN;
CREATE TABLE users (
    id            TEXT PRIMARY KEY,
    username      TEXT NOT NULL UNIQUE,
    display_name  TEXT,
    password_hash TEXT NOT NULL,
    is_admin      INTEGER NOT NULL DEFAULT 0,
    disabled      INTEGER NOT NULL DEFAULT 0,
    created_at    TEXT NOT NULL,
    updated_at    TEXT NOT NULL
);
CREATE TABLE projects (
    id         TEXT PRIMARY KEY,
    name       TEXT NOT NULL UNIQUE,
    created_at TEXT NOT NULL
);
CREATE TABLE project_members (
    project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    user_id    TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    PRIMARY KEY (project_id, user_id)
);
CREATE TABLE swarms (
    id            TEXT PRIMARY KEY,
    project_id    TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    owner_id      TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    name          TEXT NOT NULL,
    atespace_name TEXT NOT NULL UNIQUE,
    atespace_uid  TEXT,
    state         TEXT NOT NULL DEFAULT 'provisioning',
    created_at    TEXT NOT NULL,
    updated_at    TEXT NOT NULL,
    retry         TEXT NOT NULL DEFAULT '' CHECK (retry IN ('', 'create', 'delete')),
    graph         BLOB,
    execution     TEXT NOT NULL DEFAULT 'idle' CHECK (execution IN ('idle', 'running', 'waiting', 'succeeded', 'failed', 'stopped')),
    definition_name     TEXT,
    definition_version  INTEGER,
    definition_revision TEXT
, execution_at TEXT);
CREATE TABLE sessions (
    token_hash TEXT PRIMARY KEY,
    user_id    TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    created_at TEXT NOT NULL,
    expires_at TEXT,
    data       BLOB
, kind TEXT NOT NULL DEFAULT 'web' CHECK (kind IN ('web', 'telegram')));
CREATE TABLE swarm_members (
    swarm_id TEXT NOT NULL REFERENCES swarms(id) ON DELETE CASCADE,
    user_id  TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    role     TEXT NOT NULL CHECK (role IN ('owner', 'editor', 'viewer')),
    PRIMARY KEY (swarm_id, user_id)
);
CREATE TABLE project_capacity (
    project_id TEXT PRIMARY KEY NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    worker_selector TEXT NOT NULL CHECK (json_valid(worker_selector) AND json_type(worker_selector) = 'object'),
    max_swarms INTEGER CHECK (max_swarms >= 0),
    max_actors INTEGER CHECK (max_actors >= 0),
    max_cpu_millicores INTEGER CHECK (max_cpu_millicores >= 0),
    max_memory_bytes INTEGER CHECK (max_memory_bytes >= 0)
);
CREATE TABLE managed_pools (
    uid TEXT PRIMARY KEY NOT NULL,
    name TEXT NOT NULL,
    connection TEXT NOT NULL,
    source TEXT NOT NULL,
    source_fingerprint TEXT NOT NULL,
    labels TEXT NOT NULL,
    max_actors INTEGER NOT NULL CHECK (max_actors >= 0),
    cpu_millicores INTEGER NOT NULL CHECK (cpu_millicores >= 0),
    memory_bytes INTEGER NOT NULL CHECK (memory_bytes >= 0),
    disk_bytes INTEGER NOT NULL CHECK (disk_bytes >= 0),
    template TEXT NOT NULL,
    state TEXT NOT NULL CHECK (state IN ('enabled', 'draining', 'deleted')),
    revision INTEGER NOT NULL CHECK (revision > 0),
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);
CREATE TABLE managed_actors (
    uid TEXT PRIMARY KEY NOT NULL,
    name TEXT NOT NULL,
    swarm_id TEXT NOT NULL,
    atespace_uid TEXT NOT NULL,
    pool_uid TEXT NOT NULL REFERENCES managed_pools(uid),
    cluster_identity TEXT NOT NULL,
    source_fingerprint TEXT NOT NULL,
    template TEXT NOT NULL,
    incarnation INTEGER NOT NULL CHECK (incarnation > 0),
    phase TEXT NOT NULL CHECK (phase IN ('provisioning', 'running', 'stopping', 'stopped', 'error', 'deleting', 'deleted')),
    desired TEXT NOT NULL CHECK (desired IN ('running', 'stopped', 'deleted')),
    cpu_millicores INTEGER NOT NULL CHECK (cpu_millicores > 0),
    memory_bytes INTEGER NOT NULL CHECK (memory_bytes > 0),
    disk_bytes INTEGER NOT NULL CHECK (disk_bytes > 0),
    ctid INTEGER NOT NULL CHECK (ctid > 0),
    owner_nonce TEXT NOT NULL,
    operation_id TEXT NOT NULL,
    operation TEXT NOT NULL CHECK (operation IN ('create', 'start', 'stop', 'delete', 'reset')),
    upid TEXT NOT NULL,
    error TEXT NOT NULL,
    revision INTEGER NOT NULL CHECK (revision > 0),
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    deleted_at TEXT
,stage TEXT NOT NULL DEFAULT 'reconcile' CHECK (stage IN ('reconcile', 'create', 'start', 'stop', 'delete', 'done')),role TEXT NOT NULL DEFAULT 'worker' CHECK (role IN ('worker', 'master')),delegator_id TEXT NOT NULL DEFAULT '',parent_uid TEXT NOT NULL DEFAULT '',origin TEXT NOT NULL DEFAULT '', actor_class TEXT NOT NULL DEFAULT 'persistent' CHECK (actor_class IN ('persistent','ephemeral') AND (actor_class='persistent' OR (role='worker' AND delegator_id='' AND parent_uid<>''))));
CREATE TABLE managed_connections (
	uid TEXT PRIMARY KEY,
	name TEXT NOT NULL UNIQUE,
	endpoint TEXT NOT NULL,
	token_id TEXT NOT NULL,
	token_secret TEXT NOT NULL,
	ca_pem TEXT NOT NULL,
	node TEXT NOT NULL,
	resource_pool TEXT NOT NULL,
	storage TEXT NOT NULL,
	network TEXT NOT NULL,
	created_at TEXT NOT NULL,
	updated_at TEXT NOT NULL
,runtime_config TEXT NOT NULL DEFAULT '');
CREATE TABLE coordination_claims (
    project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    kind TEXT NOT NULL CHECK (kind IN ('dispatch', 'landing', 'workspace')),
    request_id TEXT NOT NULL CHECK (request_id <> ''),
    payload TEXT NOT NULL,
    slot TEXT,
    PRIMARY KEY (project_id, kind, request_id),
    UNIQUE (project_id, kind, slot)
);
CREATE TABLE command_project_details (
    project_id TEXT PRIMARY KEY REFERENCES projects(id) ON DELETE CASCADE,
    description TEXT NOT NULL DEFAULT ''
);
CREATE TABLE project_secret_revisions (
    project_id TEXT PRIMARY KEY REFERENCES projects(id) ON DELETE CASCADE,
    revision INTEGER NOT NULL CHECK (revision >= 0)
);
CREATE TABLE project_secret_files (
    project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    data BLOB NOT NULL CHECK (length(data) <= 524288),
    PRIMARY KEY (project_id, name)
);
CREATE TABLE project_secret_vars (
    project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    value TEXT NOT NULL CHECK (length(CAST(value AS BLOB)) <= 16384),
    PRIMARY KEY (project_id, name)
);
CREATE TABLE project_repositories (
    project_id TEXT PRIMARY KEY REFERENCES projects(id) ON DELETE CASCADE,
    origin TEXT NOT NULL CHECK (origin <> '' AND length(CAST(origin AS BLOB)) <= 1024)
);
CREATE TABLE project_git_credentials (
    project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    name TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 63),
    repository TEXT NOT NULL CHECK (repository <> '' AND length(CAST(repository AS BLOB)) <= 1024),
    username TEXT NOT NULL CHECK (username <> '' AND length(CAST(username AS BLOB)) <= 256),
    token TEXT NOT NULL CHECK (token <> '' AND length(CAST(token AS BLOB)) <= 4096),
    PRIMARY KEY (project_id, name)
);
CREATE TABLE project_git_credential_refs (
    project_id TEXT PRIMARY KEY REFERENCES projects(id) ON DELETE CASCADE,
    name TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 63)
);
CREATE TABLE swarm_steps (
    swarm_id TEXT NOT NULL REFERENCES swarms(id) ON DELETE CASCADE,
    sequence INTEGER NOT NULL,
    node_id TEXT NOT NULL,
    state TEXT NOT NULL CHECK (state IN ('pending', 'attesting', 'delivering', 'inflight', 'unconfirmed', 'refused', 'waiting', 'answered', 'completed', 'stopped')),
    started_at TEXT,
    finished_at TEXT,
    outcome TEXT,
    actor_uid TEXT,
    actor_incarnation INTEGER,
    request_id TEXT,
    attested_commit TEXT CHECK (attested_commit IS NULL OR (length(attested_commit) = 40 AND attested_commit NOT GLOB '*[^0-9a-f]*')),
    detail TEXT CHECK (detail IS NULL OR length(CAST(detail AS BLOB)) BETWEEN 1 AND 1024),
    report TEXT CHECK (report IS NULL OR length(CAST(report AS BLOB)) BETWEEN 1 AND 16384),
    goal TEXT CHECK (goal IS NULL OR length(CAST(goal AS BLOB)) BETWEEN 1 AND 4096),
    source_commit TEXT CHECK (source_commit IS NULL OR (length(source_commit) = 40 AND source_commit NOT GLOB '*[^0-9a-f]*')),
    PRIMARY KEY (swarm_id, sequence),
    UNIQUE (swarm_id, request_id),
    CHECK (report IS NULL OR (state = 'completed' AND outcome IS NOT NULL)),
    CHECK ((goal IS NULL) = (source_commit IS NULL))
);
CREATE TABLE swarm_role_bindings (
    swarm_id TEXT NOT NULL REFERENCES swarms(id) ON DELETE CASCADE,
    role TEXT NOT NULL,
    actor_uid TEXT NOT NULL,
    actor_incarnation INTEGER NOT NULL CHECK (actor_incarnation > 0),
    PRIMARY KEY (swarm_id, role)
);
CREATE TABLE workflow_definitions (
    project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    yaml TEXT NOT NULL,
    version INTEGER NOT NULL CHECK (version > 0),
    published_at TEXT, revision TEXT, PRIMARY KEY (project_id, name)
);
CREATE TABLE workflow_revision_counters (
    project_id TEXT NOT NULL PRIMARY KEY REFERENCES projects(id) ON DELETE CASCADE,
    version INTEGER NOT NULL CHECK (typeof(version) = 'integer' AND version > 0)
);
CREATE TABLE pipeline_sources (
    swarm_id TEXT NOT NULL PRIMARY KEY REFERENCES swarms(id) ON DELETE CASCADE,
    origin TEXT NOT NULL
);
CREATE TABLE swarm_requests (
    id TEXT PRIMARY KEY,
    swarm_id TEXT NOT NULL REFERENCES swarms(id) ON DELETE CASCADE,
    sequence INTEGER,
    origin TEXT NOT NULL CHECK (origin IN ('node', 'actor')),
    actor_uid TEXT,
    actor_incarnation INTEGER,
    kind TEXT NOT NULL CHECK (kind IN ('choice', 'text', 'confirm')),
    question TEXT NOT NULL,
    context TEXT,
    options BLOB,
    state TEXT NOT NULL CHECK (state IN ('open', 'answered', 'cancelled')),
    created_at TEXT NOT NULL,
    answered_at TEXT,
    answered_by TEXT REFERENCES users(id),
    outcome TEXT,
    response TEXT,
    delivery TEXT CHECK (delivery IN ('pending', 'delivered', 'failed', 'unconfirmed')),
    FOREIGN KEY (swarm_id, sequence) REFERENCES swarm_steps(swarm_id, sequence),
    CHECK (origin <> 'node' OR (sequence IS NOT NULL AND kind = 'choice' AND actor_uid IS NULL)),
    CHECK (origin <> 'actor' OR (sequence IS NULL AND actor_uid IS NOT NULL AND actor_incarnation > 0 AND outcome IS NULL)),
    CHECK (origin <> 'actor' OR length(question) > 0),
    CHECK (kind <> 'choice' OR options IS NOT NULL),
    CHECK (state = 'answered' OR (answered_at IS NULL AND answered_by IS NULL AND outcome IS NULL AND response IS NULL)),
    CHECK (state <> 'answered' OR (answered_at IS NOT NULL AND answered_by IS NOT NULL)),
    CHECK (origin <> 'node' OR state <> 'answered' OR outcome IS NOT NULL),
    CHECK ((delivery IS NOT NULL) = (origin = 'actor' AND state = 'answered'))
);
CREATE TABLE user_telegram_links (
    user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
    bot_token TEXT CHECK (length(bot_token) > 0),
    bot_username TEXT UNIQUE COLLATE NOCASE CHECK (length(bot_username) > 0),
    chat_id INTEGER UNIQUE CHECK (chat_id > 0),
    telegram_user_id INTEGER,
    link_code_hash TEXT UNIQUE,
    link_code_expires_at TEXT,
    session_hash TEXT UNIQUE REFERENCES sessions(token_hash),
    state TEXT NOT NULL CHECK (state IN ('unlinked', 'linked', 'error')),
    reason TEXT CHECK (length(reason) > 0),
    events TEXT NOT NULL CHECK (json_valid(events) AND json_type(events) = 'array'),
    updated_at TEXT NOT NULL, default_swarm_id TEXT REFERENCES swarms(id) ON DELETE SET NULL, telegram_username TEXT CHECK (telegram_username IS NULL OR (state = 'linked' AND length(telegram_username) BETWEEN 1 AND 32 AND telegram_username NOT GLOB '*[^A-Za-z0-9_]*')),
    CHECK ((bot_token IS NULL) = (bot_username IS NULL)),
    CHECK ((link_code_hash IS NULL) = (link_code_expires_at IS NULL)),
    CHECK ((state = 'linked') = (session_hash IS NOT NULL)),
    CHECK ((state = 'linked') = (chat_id IS NOT NULL)),
    CHECK ((state = 'linked') = (telegram_user_id IS NOT NULL)),
    CHECK (chat_id = telegram_user_id),
    CHECK (state <> 'linked' OR link_code_hash IS NULL),
    CHECK ((state = 'error') = (reason IS NOT NULL))
);
CREATE TABLE telegram_outbox (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    kind TEXT NOT NULL CHECK (kind IN ('request_opened', 'request_answered', 'answer_delivery', 'pass_started', 'pass_finished', 'step_failed', 'actor_question')),
    ref TEXT NOT NULL CHECK (length(ref) > 0),
    payload TEXT NOT NULL,
    state TEXT NOT NULL CHECK (state IN ('pending', 'sent', 'failed', 'unconfirmed')),
    attempts INTEGER NOT NULL CHECK (attempts >= 0),
    settled_attempts INTEGER NOT NULL CHECK (settled_attempts >= 0),
    telegram_message_id INTEGER,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL, force_reply INTEGER NOT NULL DEFAULT 0 CHECK (force_reply IN (0, 1) AND (force_reply = 0 OR state = 'sent')),
    CHECK ((state = 'sent') = (telegram_message_id IS NOT NULL)),
    CHECK (attempts - settled_attempts IN (0, 1)),
    CHECK (state = 'pending' OR settled_attempts > 0),
    CHECK (attempts = settled_attempts OR state IN ('pending', 'unconfirmed'))
);
CREATE TABLE gitlab_bindings (
    project_id TEXT PRIMARY KEY NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    repository TEXT NOT NULL,
    api_origin TEXT NOT NULL,
    gitlab_project_id INTEGER NOT NULL CHECK (gitlab_project_id > 0),
    target_branch TEXT NOT NULL CHECK (length(target_branch) > 0),
    credential_ref TEXT NOT NULL CHECK (length(credential_ref) > 0),
    enabled INTEGER NOT NULL CHECK (enabled IN (0, 1)),
    revision INTEGER NOT NULL CHECK (revision > 0)
);
CREATE TABLE gitlab_grants (
    id TEXT PRIMARY KEY NOT NULL,
    project_id TEXT NOT NULL,
    swarm_id TEXT NOT NULL,
    atespace_uid TEXT NOT NULL,
    actor_uid TEXT NOT NULL,
    incarnation INTEGER NOT NULL CHECK (incarnation > 0),
    human_id TEXT NOT NULL,
    binding_revision INTEGER NOT NULL CHECK (binding_revision > 0),
    can_read INTEGER NOT NULL CHECK (can_read IN (0, 1)),
    can_create INTEGER NOT NULL CHECK (can_create IN (0, 1)),
    can_propose INTEGER NOT NULL CHECK (can_propose IN (0, 1)),
    expires_at INTEGER NOT NULL,
    revoked INTEGER NOT NULL DEFAULT 0 CHECK (revoked IN (0, 1)),
    revision INTEGER NOT NULL CHECK (revision > 0)
);
CREATE TABLE gitlab_operations (
    id TEXT PRIMARY KEY NOT NULL,
    project_id TEXT NOT NULL,
    swarm_id TEXT NOT NULL,
    atespace_uid TEXT NOT NULL,
    actor_uid TEXT NOT NULL,
    incarnation INTEGER NOT NULL CHECK (incarnation > 0),
    kind TEXT NOT NULL CHECK (kind IN ('create', 'propose')),
    request_id TEXT NOT NULL CHECK (length(request_id) > 0),
    grant_id TEXT NOT NULL REFERENCES gitlab_grants(id),
    binding_revision INTEGER NOT NULL CHECK (binding_revision > 0),
    binding_snapshot TEXT NOT NULL CHECK (json_valid(binding_snapshot)),
    payload_hash TEXT NOT NULL CHECK (length(payload_hash) = 64 AND payload_hash NOT GLOB '*[^0-9a-f]*'),
    snapshot TEXT NOT NULL,
    state TEXT NOT NULL CHECK (state IN ('reserved', 'sending', 'completed', 'refused', 'unknown')),
    revision INTEGER NOT NULL CHECK (revision > 0),
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    UNIQUE (project_id, actor_uid, incarnation, kind, request_id)
);
CREATE TABLE gitlab_approvals (
    operation_id TEXT PRIMARY KEY NOT NULL REFERENCES gitlab_operations(id),
    human_id TEXT NOT NULL,
    session_hash TEXT NOT NULL,
    expires_at INTEGER NOT NULL,
    state TEXT NOT NULL CHECK (state IN ('approved', 'revoked', 'claimed')),
    revision INTEGER NOT NULL CHECK (revision > 0)
);
CREATE TABLE gitlab_proposal_states (
 operation_id TEXT PRIMARY KEY NOT NULL REFERENCES gitlab_operations(id),
 state TEXT NOT NULL CHECK (state IN ('pending','rejected','stale')),
 revision INTEGER NOT NULL CHECK (revision > 0),
 human_id TEXT NOT NULL DEFAULT '',
 session_hash TEXT NOT NULL DEFAULT ''
);
CREATE TABLE swarm_child_joins (
 swarm_id TEXT NOT NULL,
 parent_sequence INTEGER NOT NULL CHECK (parent_sequence > 0),
 pass INTEGER NOT NULL CHECK (pass > 0 AND pass <= parent_sequence),
 project_id TEXT NOT NULL,
 atespace_uid TEXT NOT NULL,
 parent_uid TEXT NOT NULL,
 parent_incarnation INTEGER NOT NULL CHECK (parent_incarnation > 0),
 parent_request_id TEXT NOT NULL,
 mode TEXT NOT NULL CHECK (mode IN ('all','any','quorum')),
 total INTEGER NOT NULL CHECK (total BETWEEN 1 AND 64),
 quorum INTEGER NOT NULL CHECK ((mode='quorum' AND quorum BETWEEN 1 AND total) OR (mode IN ('all','any') AND quorum=0)),
 remaining TEXT NOT NULL CHECK (remaining='retain'),
 created_at TEXT NOT NULL,
 state TEXT NOT NULL DEFAULT 'open' CHECK (state IN ('open','aborted')),
 revision INTEGER NOT NULL DEFAULT 1,
 aborted_by TEXT,
 aborted_at TEXT,
 CHECK ((state='open' AND revision=1 AND aborted_by IS NULL AND aborted_at IS NULL) OR (state='aborted' AND revision=2 AND aborted_by IS NOT NULL AND length(aborted_by)>0 AND aborted_at IS NOT NULL)),
 PRIMARY KEY (swarm_id,parent_sequence),
 FOREIGN KEY (swarm_id,parent_sequence) REFERENCES swarm_steps(swarm_id,sequence) ON DELETE RESTRICT,
 FOREIGN KEY (swarm_id,pass) REFERENCES swarm_steps(swarm_id,sequence) ON DELETE RESTRICT
);
CREATE TABLE swarm_child_tasks (
 id TEXT PRIMARY KEY NOT NULL,
 swarm_id TEXT NOT NULL,
 parent_sequence INTEGER NOT NULL,
 request_id TEXT NOT NULL CHECK (length(request_id) BETWEEN 1 AND 128 AND request_id NOT GLOB '*[^a-zA-Z0-9_-]*'),
 payload TEXT NOT NULL CHECK (length(CAST(payload AS BLOB)) BETWEEN 1 AND 4096),
 actor_uid TEXT NOT NULL,
 actor_incarnation INTEGER NOT NULL CHECK (actor_incarnation > 0),
 state TEXT NOT NULL CHECK (state IN ('pending','running','completed','cancelled')),
 outcome TEXT CHECK (outcome IN ('success','fail')),
 report TEXT CHECK (report IS NULL OR length(CAST(report AS BLOB)) BETWEEN 1 AND 16384),
 revision INTEGER NOT NULL CHECK (revision > 0),
 created_at TEXT NOT NULL,
 finished_at TEXT,
 role TEXT NOT NULL DEFAULT '',
 delivery TEXT NOT NULL DEFAULT '' CHECK (delivery IN ('','queued','sending','delivered','not_sent','unconfirmed')),
 delivery_detail TEXT NOT NULL DEFAULT '' CHECK (length(CAST(delivery_detail AS BLOB))<=1024),
 CHECK ((role='' AND delivery='') OR (length(role) BETWEEN 1 AND 63 AND delivery!='')),
 CHECK (state!='pending' OR delivery IN ('','queued')),
 CHECK (state!='running' OR delivery IN ('','sending','delivered','not_sent','unconfirmed')),
 UNIQUE (swarm_id,parent_sequence,request_id),
 FOREIGN KEY (swarm_id,parent_sequence) REFERENCES swarm_child_joins(swarm_id,parent_sequence) ON DELETE RESTRICT,
 CHECK ((state='completed' AND outcome IS NOT NULL) OR (state!='completed' AND outcome IS NULL AND report IS NULL)),
 CHECK ((state IN ('completed','cancelled')) = (finished_at IS NOT NULL))
);
CREATE TABLE actor_interventions (
 id TEXT PRIMARY KEY NOT NULL,
 project_id TEXT NOT NULL,
 swarm_id TEXT NOT NULL,
 actor_uid TEXT NOT NULL,
 incarnation INTEGER NOT NULL CHECK (incarnation>0),
 human_id TEXT NOT NULL,
 caller TEXT NOT NULL,
 operation TEXT NOT NULL,
 state TEXT NOT NULL CHECK (state IN ('inflight','unconfirmed','completed')),
 created_at TEXT NOT NULL
);
CREATE TABLE actor_step_interruptions (
 intervention_id TEXT NOT NULL REFERENCES actor_interventions(id) ON DELETE RESTRICT,
 swarm_id TEXT NOT NULL,
 sequence INTEGER NOT NULL,
 PRIMARY KEY (intervention_id,swarm_id,sequence),
 FOREIGN KEY (swarm_id,sequence) REFERENCES swarm_steps(swarm_id,sequence) ON DELETE RESTRICT
);
CREATE TABLE project_managed_networks (
 project_id TEXT PRIMARY KEY NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
 policy TEXT NOT NULL CHECK (length(policy) BETWEEN 1 AND 131072 AND json_valid(policy))
);
CREATE TABLE managed_actor_networks (
 actor_uid TEXT PRIMARY KEY NOT NULL CHECK (length(actor_uid) > 0),
 policy TEXT NOT NULL CHECK (length(policy) <= 131072 AND (policy = '' OR json_valid(policy)))
);
CREATE TABLE project_workflow_policy_versions (
 project_id TEXT NOT NULL CHECK (length(project_id) > 0),
 revision INTEGER NOT NULL CHECK (revision > 0),
 rules TEXT NOT NULL CHECK (length(rules) BETWEEN 2 AND 131072 AND json_valid(rules) AND json_type(rules) = 'array'),
 created_by TEXT NOT NULL CHECK (length(created_by) > 0),
 created_at TEXT NOT NULL CHECK (length(created_at) > 0),
 PRIMARY KEY (project_id, revision)
);
CREATE TABLE project_workflow_policy_heads (
 project_id TEXT PRIMARY KEY NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
 revision INTEGER NOT NULL CHECK (revision > 0),
 FOREIGN KEY (project_id, revision) REFERENCES project_workflow_policy_versions(project_id, revision)
);
CREATE TABLE swarm_pass_policies (
 swarm_id TEXT NOT NULL CHECK (length(swarm_id) > 0),
 pass_sequence INTEGER NOT NULL CHECK (pass_sequence > 0),
 project_id TEXT NOT NULL CHECK (length(project_id) > 0),
 policy_revision INTEGER CHECK (policy_revision IS NULL OR policy_revision > 0),
 legacy_empty INTEGER NOT NULL CHECK (legacy_empty IN (0,1) AND (legacy_empty=0 OR policy_revision IS NULL)),
 PRIMARY KEY (swarm_id, pass_sequence),
 FOREIGN KEY (project_id, policy_revision) REFERENCES project_workflow_policy_versions(project_id, revision)
);
CREATE TABLE pipeline_completion_intents (
 swarm_id TEXT NOT NULL CHECK (length(swarm_id) > 0),
 sequence INTEGER NOT NULL CHECK (sequence > 0),
 pass_sequence INTEGER NOT NULL CHECK (pass_sequence > 0 AND pass_sequence <= sequence),
 request_id TEXT NOT NULL CHECK (length(request_id) BETWEEN 1 AND 4096),
 actor_uid TEXT NOT NULL CHECK (length(actor_uid) BETWEEN 1 AND 4096),
 actor_incarnation INTEGER NOT NULL CHECK (actor_incarnation > 0),
 origin TEXT NOT NULL CHECK (length(origin) BETWEEN 1 AND 1024),
 base_commit TEXT NOT NULL CHECK (length(base_commit)=40 AND base_commit NOT GLOB '*[^0-9a-f]*'),
 outcome TEXT NOT NULL CHECK (outcome IN ('success','fail')),
 report TEXT NOT NULL CHECK (length(CAST(report AS BLOB)) <= 16384),
 created_at TEXT NOT NULL CHECK (length(created_at) > 0),
 PRIMARY KEY (swarm_id,sequence),
 UNIQUE (swarm_id,request_id),
 FOREIGN KEY (swarm_id,pass_sequence) REFERENCES swarm_pass_policies(swarm_id,pass_sequence)
);
CREATE TABLE pipeline_result_observations (
 id TEXT PRIMARY KEY NOT NULL CHECK (length(id) BETWEEN 1 AND 128),
 swarm_id TEXT NOT NULL,
 sequence INTEGER NOT NULL CHECK (sequence > 0),
 request TEXT NOT NULL CHECK (length(request) BETWEEN 2 AND 8192 AND json_valid(request) AND json_type(request)='object'),
 lease TEXT NOT NULL CHECK (length(lease) BETWEEN 2 AND 8192 AND json_valid(lease) AND json_type(lease)='object'),
 state TEXT NOT NULL CHECK (state IN ('inflight','observed','refused','unconfirmed')),
 detail TEXT NOT NULL CHECK (length(CAST(detail AS BLOB)) <= 1024),
 revision INTEGER NOT NULL CHECK (revision > 0),
 UNIQUE (swarm_id,sequence),
 FOREIGN KEY (swarm_id,sequence) REFERENCES pipeline_completion_intents(swarm_id,sequence)
);
CREATE TABLE pipeline_result_evidence (
 observation_id TEXT PRIMARY KEY NOT NULL REFERENCES pipeline_result_observations(id),
 attestation TEXT NOT NULL CHECK (length(CAST(attestation AS BLOB)) BETWEEN 2 AND 98304 AND json_valid(attestation) AND json_type(attestation)='object')
);
CREATE TABLE pipeline_completion_receipts (
 swarm_id TEXT NOT NULL,
 sequence INTEGER NOT NULL CHECK (sequence > 0),
 version INTEGER NOT NULL CHECK (version=1),
 nonce TEXT NOT NULL UNIQUE CHECK (length(nonce)=43 AND nonce NOT GLOB '*[^a-zA-Z0-9_-]*'),
 created_at TEXT NOT NULL CHECK (length(created_at) > 0),
 PRIMARY KEY (swarm_id,sequence),
 FOREIGN KEY (swarm_id,sequence) REFERENCES pipeline_completion_intents(swarm_id,sequence)
);
CREATE TABLE pipeline_completion_acknowledgements (
 swarm_id TEXT NOT NULL,
 sequence INTEGER NOT NULL CHECK (sequence > 0),
 acknowledged_at TEXT NOT NULL CHECK (length(acknowledged_at) > 0),
 PRIMARY KEY (swarm_id,sequence),
 FOREIGN KEY (swarm_id,sequence) REFERENCES pipeline_completion_receipts(swarm_id,sequence)
);
CREATE TABLE pipeline_policy_candidates (
 id TEXT NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 128),
 version INTEGER NOT NULL CHECK (version=1),
 swarm_id TEXT NOT NULL,
 sequence INTEGER NOT NULL CHECK (sequence > 0),
 pass_sequence INTEGER NOT NULL CHECK (pass_sequence > 0 AND pass_sequence <= sequence),
 boundary TEXT NOT NULL CHECK (boundary IN ('entry','result')),
 policy_revision INTEGER NOT NULL CHECK (policy_revision > 0),
 evidence_id TEXT,
 preview TEXT NOT NULL CHECK (length(CAST(preview AS BLOB)) <= 8388608 AND json_valid(preview) AND json_type(preview)='object'),
 created_at TEXT NOT NULL CHECK (length(created_at)>0),
 UNIQUE (swarm_id,sequence,boundary),
 FOREIGN KEY (swarm_id,pass_sequence) REFERENCES swarm_pass_policies(swarm_id,pass_sequence),
 FOREIGN KEY (evidence_id) REFERENCES pipeline_result_observations(id),
 CHECK ((boundary='entry' AND evidence_id IS NULL) OR (boundary='result' AND evidence_id IS NOT NULL)),
 CHECK (json_extract(preview,'$.SwarmID') IS swarm_id AND json_extract(preview,'$.Policy.SwarmID') IS swarm_id AND json_extract(preview,'$.Sequence') IS sequence AND json_extract(preview,'$.Policy.Pass') IS pass_sequence AND json_extract(preview,'$.Policy.Revision') IS policy_revision AND json_extract(preview,'$.EvidenceID') IS COALESCE(evidence_id,'')),
 CHECK (json_extract(preview,'$.Input.Initial') IS (boundary='entry')),
 CHECK (COALESCE(json_extract(preview,'$.Decision.State'),'') IN ('allowed','blocked','waiting_human','waiting_review','denied'))
);
CREATE TABLE pipeline_policy_confirmations (
 candidate_id TEXT NOT NULL PRIMARY KEY,
 swarm_id TEXT NOT NULL,
 revision INTEGER NOT NULL CHECK (revision=2),
 user_id TEXT NOT NULL CHECK (length(user_id)>0),
 answer TEXT NOT NULL CHECK (answer IN ('yes','no')),
 answered_at TEXT NOT NULL CHECK (length(answered_at)>0),
 FOREIGN KEY (candidate_id) REFERENCES pipeline_policy_candidates(id)
);
CREATE TABLE actor_deliveries (
 id TEXT PRIMARY KEY,
 swarm_id TEXT NOT NULL,
 source_kind TEXT NOT NULL CHECK (source_kind IN ('step','answer','child')),
 source_id TEXT NOT NULL CHECK (length(source_id) BETWEEN 1 AND 512),
 request_id TEXT NOT NULL,
 attested_commit TEXT NOT NULL,
 actor_uid TEXT NOT NULL,
 incarnation INTEGER NOT NULL CHECK (incarnation>0),
 atespace_uid TEXT NOT NULL CHECK (length(atespace_uid)>0),
 journal_id TEXT NOT NULL CHECK (length(journal_id)=64 AND journal_id NOT GLOB '*[^0-9a-f]*'),
 payload TEXT NOT NULL CHECK (json_valid(payload) AND json_type(payload)='object' AND length(CAST(payload AS BLOB))<=131072),
 probe_only INTEGER NOT NULL CHECK (probe_only IN (0,1)),
 created_at TEXT NOT NULL CHECK (length(created_at)>0),
 UNIQUE (swarm_id,source_kind,source_id),
 CHECK ((source_kind='answer' AND request_id='' AND attested_commit='') OR (source_kind IN ('step','child') AND length(request_id)>0 AND length(attested_commit)>0))
);
CREATE TABLE actor_delivery_attempts (
 delivery_id TEXT NOT NULL REFERENCES actor_deliveries(id),
 number INTEGER NOT NULL CHECK (number BETWEEN 1 AND 8),
 mode TEXT NOT NULL CHECK (mode IN ('send','probe')),
 created_at TEXT NOT NULL CHECK (length(created_at)>0),
 deadline_at TEXT NOT NULL CHECK (length(deadline_at)>0),
 PRIMARY KEY (delivery_id,number)
);
CREATE TABLE actor_delivery_outcomes (
 delivery_id TEXT NOT NULL,
 number INTEGER NOT NULL,
 outcome TEXT NOT NULL CHECK (outcome IN ('delivered','duplicate','not_sent','unconfirmed')),
 detail TEXT NOT NULL CHECK (length(detail)<=512),
 observed_at TEXT NOT NULL CHECK (length(observed_at)>0),
 PRIMARY KEY (delivery_id,number),
 FOREIGN KEY (delivery_id,number) REFERENCES actor_delivery_attempts(delivery_id,number)
);
CREATE TABLE swarm_request_pass_contexts (
 request_id TEXT PRIMARY KEY NOT NULL CHECK (length(request_id) BETWEEN 1 AND 128),
 swarm_id TEXT NOT NULL CHECK (length(swarm_id)>0),
 pass_sequence INTEGER NOT NULL CHECK (pass_sequence>0),
 observed_sequence INTEGER NOT NULL CHECK (observed_sequence>=pass_sequence)
);
CREATE TABLE ephemeral_child_intents (
 id TEXT PRIMARY KEY NOT NULL CHECK(id<>''),
 swarm_id TEXT NOT NULL CHECK(swarm_id<>''),
 parent_sequence INTEGER NOT NULL CHECK(parent_sequence>0),
 pass INTEGER NOT NULL CHECK(pass>0 AND pass<=parent_sequence),
 project_id TEXT NOT NULL CHECK(project_id<>''),
 atespace_uid TEXT NOT NULL CHECK(atespace_uid<>''),
 parent_uid TEXT NOT NULL CHECK(parent_uid<>''),
 parent_incarnation INTEGER NOT NULL CHECK(parent_incarnation>0),
 parent_request_id TEXT NOT NULL CHECK(parent_request_id<>''),
 request_id TEXT NOT NULL CHECK(request_id<>''),
 payload TEXT NOT NULL CHECK(length(CAST(payload AS BLOB)) BETWEEN 1 AND 4096),
 pool_uid TEXT NOT NULL CHECK(pool_uid<>''),
 source_fingerprint TEXT NOT NULL CHECK(source_fingerprint<>''),
 template TEXT NOT NULL CHECK(template<>''),
 source_commit TEXT NOT NULL CHECK(source_commit<>''),
 origin TEXT NOT NULL CHECK(origin<>''),
 created_at TEXT NOT NULL CHECK(created_at<>''),
 UNIQUE(swarm_id,parent_sequence,request_id)
);
CREATE TABLE ephemeral_child_allocations (
 intent_id TEXT PRIMARY KEY NOT NULL REFERENCES ephemeral_child_intents(id) ON DELETE RESTRICT,
 actor_uid TEXT NOT NULL UNIQUE CHECK(actor_uid<>''),
 actor_incarnation INTEGER NOT NULL CHECK(actor_incarnation=1),
 create_operation_id TEXT NOT NULL CHECK(create_operation_id<>''),
 reservation_hash TEXT NOT NULL CHECK(length(reservation_hash)=64 AND reservation_hash NOT GLOB '*[^0-9a-f]*'),
 created_at TEXT NOT NULL CHECK(created_at<>'')
);
CREATE TABLE ephemeral_child_attestations (
 intent_id TEXT PRIMARY KEY NOT NULL REFERENCES ephemeral_child_allocations(intent_id) ON DELETE RESTRICT,
 attempt_id TEXT NOT NULL CHECK(length(attempt_id) BETWEEN 1 AND 128 AND attempt_id NOT GLOB '*[^a-zA-Z0-9_-]*'),
 actor_uid TEXT NOT NULL UNIQUE CHECK(actor_uid<>''),
 actor_incarnation INTEGER NOT NULL CHECK(actor_incarnation=1),
 origin TEXT NOT NULL CHECK(origin<>''),
 source_commit TEXT NOT NULL CHECK(source_commit<>''),
 lease TEXT NOT NULL CHECK(json_valid(lease)),
 state TEXT NOT NULL CHECK(state IN ('pending','unconfirmed','attested')),
 attested_origin TEXT NOT NULL,
 attested_commit TEXT NOT NULL,
 created_at TEXT NOT NULL CHECK(created_at<>''),
 updated_at TEXT NOT NULL CHECK(updated_at<>''),
 CHECK((state='attested' AND attested_origin=origin AND attested_commit=source_commit) OR (state IN ('pending','unconfirmed') AND attested_origin='' AND attested_commit=''))
);
CREATE TABLE ephemeral_child_create_grants (
 intent_id TEXT PRIMARY KEY NOT NULL REFERENCES ephemeral_child_allocations(intent_id) ON DELETE RESTRICT,
 state TEXT NOT NULL CHECK(state IN ('queued','reserved','legacy')),
 created_at TEXT NOT NULL CHECK(created_at<>''),
 reserved_at TEXT NOT NULL DEFAULT '' CHECK((state='reserved' AND reserved_at<>'') OR (state IN ('queued','legacy') AND reserved_at=''))
);
CREATE TABLE ephemeral_child_result_seals (
 intent_id TEXT PRIMARY KEY NOT NULL REFERENCES ephemeral_child_allocations(intent_id) ON DELETE RESTRICT,
 child_id TEXT NOT NULL UNIQUE REFERENCES swarm_child_tasks(id) ON DELETE RESTRICT,
 child_revision INTEGER NOT NULL CHECK(child_revision>=3),
 outcome TEXT NOT NULL CHECK(outcome IN ('success','fail')),
 report_hash TEXT NOT NULL CHECK(length(report_hash)=64 AND report_hash NOT GLOB '*[^0-9a-f]*'),
 parent_outcome TEXT NOT NULL CHECK(parent_outcome IN ('success','fail')),
 parent_report_hash TEXT NOT NULL CHECK(length(parent_report_hash)=64 AND parent_report_hash NOT GLOB '*[^0-9a-f]*'),
 created_at TEXT NOT NULL CHECK(created_at<>'')
);
CREATE TABLE ephemeral_child_lifecycles (
 intent_id TEXT NOT NULL REFERENCES ephemeral_child_allocations(intent_id) ON DELETE RESTRICT,
 kind TEXT NOT NULL CHECK(kind IN ('start','cleanup','failure_cleanup')),
 operation_id TEXT NOT NULL UNIQUE CHECK(operation_id<>''),
 created_at TEXT NOT NULL CHECK(created_at<>''),
 PRIMARY KEY(intent_id,kind)
);
CREATE TABLE ephemeral_child_failures (
 intent_id TEXT PRIMARY KEY NOT NULL REFERENCES ephemeral_child_intents(id) ON DELETE RESTRICT,
 reason TEXT NOT NULL CHECK(length(CAST(reason AS BLOB)) BETWEEN 1 AND 1024 AND length(trim(reason))>0),
 failed_at TEXT NOT NULL CHECK(failed_at<>'')
);
CREATE TABLE owner_managed_actor_lineage (
 actor_uid TEXT NOT NULL CHECK(actor_uid!=''),
 incarnation INTEGER NOT NULL CHECK(incarnation>0),
 operation_id TEXT NOT NULL CHECK(operation_id!=''),
 operation TEXT NOT NULL CHECK(operation IN ('reset','start')),
 prior_incarnation INTEGER NOT NULL CHECK(prior_incarnation>0),
 prior_operation_id TEXT NOT NULL CHECK(prior_operation_id!=''),
 origin_id TEXT NOT NULL REFERENCES actor_interventions(id) ON DELETE RESTRICT,
 PRIMARY KEY(actor_uid,incarnation,operation_id),
 CHECK((operation='reset' AND incarnation=prior_incarnation+1 AND operation_id=prior_operation_id)
 OR (operation='start' AND incarnation=prior_incarnation AND operation_id!=prior_operation_id))
);
CREATE TABLE ephemeral_child_executor_failures (
 intent_id TEXT PRIMARY KEY NOT NULL REFERENCES ephemeral_child_allocations(intent_id) ON DELETE RESTRICT,
 child_id TEXT NOT NULL UNIQUE REFERENCES swarm_child_tasks(id) ON DELETE RESTRICT,
 reason TEXT NOT NULL CHECK(length(CAST(reason AS BLOB)) BETWEEN 1 AND 1024 AND length(trim(reason))>0),
 failed_at TEXT NOT NULL CHECK(failed_at<>'')
);
