CREATE TRIGGER ephemeral_child_failure_update_guard BEFORE UPDATE ON ephemeral_child_failures BEGIN SELECT RAISE(ABORT,'ephemeral child failure is immutable'); END;
CREATE TRIGGER ephemeral_child_failure_delete_guard BEFORE DELETE ON ephemeral_child_failures BEGIN SELECT RAISE(ABORT,'ephemeral child failure is immutable'); END;
CREATE TRIGGER ephemeral_failed_child_insert_guard BEFORE INSERT ON swarm_child_tasks WHEN EXISTS(SELECT 1 FROM ephemeral_child_intents e JOIN ephemeral_child_failures f ON f.intent_id=e.id WHERE e.swarm_id=NEW.swarm_id AND e.parent_sequence=NEW.parent_sequence AND e.request_id=NEW.request_id) BEGIN SELECT RAISE(ABORT,'failed ephemeral intent cannot register a child'); END;
CREATE TRIGGER ephemeral_failed_allocation_guard BEFORE INSERT ON ephemeral_child_allocations WHEN EXISTS(SELECT 1 FROM ephemeral_child_failures WHERE intent_id=NEW.intent_id) BEGIN SELECT RAISE(ABORT,'failed ephemeral intent cannot allocate'); END;
CREATE TRIGGER ephemeral_failed_attestation_guard BEFORE INSERT ON ephemeral_child_attestations WHEN EXISTS(SELECT 1 FROM ephemeral_child_failures WHERE intent_id=NEW.intent_id) BEGIN SELECT RAISE(ABORT,'failed ephemeral intent cannot attest'); END;
CREATE TRIGGER ephemeral_failed_attestation_proof_guard BEFORE UPDATE ON ephemeral_child_attestations WHEN NEW.state='attested' AND EXISTS(SELECT 1 FROM ephemeral_child_failures WHERE intent_id=NEW.intent_id) BEGIN SELECT RAISE(ABORT,'failed ephemeral intent cannot accept proof'); END;
CREATE TRIGGER ephemeral_failed_lifecycle_guard BEFORE INSERT ON ephemeral_child_lifecycles WHEN NEW.kind!='failure_cleanup' AND EXISTS(SELECT 1 FROM ephemeral_child_failures WHERE intent_id=NEW.intent_id) BEGIN SELECT RAISE(ABORT,'failed ephemeral intent cannot begin automatic lifecycle'); END;
CREATE TRIGGER owner_managed_actor_lineage_insert BEFORE INSERT ON owner_managed_actor_lineage WHEN
 EXISTS(SELECT 1 FROM owner_managed_actor_lineage WHERE actor_uid=NEW.actor_uid AND incarnation=NEW.incarnation AND operation_id=NEW.operation_id)
 OR NOT EXISTS(SELECT 1 FROM actor_interventions r JOIN managed_actors a ON a.uid=r.actor_uid JOIN swarms sw ON sw.id=a.swarm_id
 WHERE r.id=NEW.origin_id AND r.state='completed' AND r.operation='reset'
 AND r.actor_uid=NEW.actor_uid AND r.swarm_id=a.swarm_id AND r.project_id=sw.project_id
 AND a.incarnation=NEW.incarnation AND a.operation_id=NEW.operation_id AND a.operation=NEW.operation
 AND ((NEW.operation='reset' AND a.stage='create') OR (NEW.operation='start' AND a.stage='start'))
 AND ((NEW.operation='reset' AND r.incarnation=NEW.prior_incarnation AND r.id=NEW.prior_operation_id)
 OR EXISTS(SELECT 1 FROM owner_managed_actor_lineage p WHERE p.actor_uid=NEW.actor_uid AND p.incarnation=NEW.prior_incarnation AND p.operation_id=NEW.prior_operation_id AND p.operation='reset' AND p.origin_id=r.id)))
 BEGIN SELECT RAISE(ABORT,'derived owner lineage requires exact completed reset origin and managed transition'); END;
CREATE TRIGGER owner_managed_actor_lineage_no_update BEFORE UPDATE ON owner_managed_actor_lineage
 BEGIN SELECT RAISE(ABORT,'derived owner lineage is immutable'); END;
CREATE TRIGGER owner_managed_actor_lineage_no_delete BEFORE DELETE ON owner_managed_actor_lineage
 BEGIN SELECT RAISE(ABORT,'derived owner lineage is retained'); END;
CREATE TRIGGER ephemeral_executor_failure_insert_guard BEFORE INSERT ON ephemeral_child_executor_failures WHEN
 EXISTS(SELECT 1 FROM ephemeral_child_executor_failures WHERE intent_id=NEW.intent_id OR child_id=NEW.child_id)
 OR NOT EXISTS(SELECT 1 FROM ephemeral_child_intents e JOIN ephemeral_child_allocations a ON a.intent_id=e.id
 JOIN ephemeral_child_attestations p ON p.intent_id=e.id AND p.state='attested' AND p.actor_uid=a.actor_uid AND p.actor_incarnation=a.actor_incarnation AND p.origin=e.origin AND p.source_commit=e.source_commit AND p.attested_origin=e.origin AND p.attested_commit=e.source_commit
 JOIN swarm_child_tasks c ON c.swarm_id=e.swarm_id AND c.parent_sequence=e.parent_sequence AND c.request_id=e.request_id AND c.payload=e.payload AND c.actor_uid=a.actor_uid AND c.actor_incarnation=a.actor_incarnation
 JOIN swarm_child_joins j ON j.swarm_id=e.swarm_id AND j.parent_sequence=e.parent_sequence AND j.state='open' AND j.pass=e.pass AND j.project_id=e.project_id AND j.atespace_uid=e.atespace_uid AND j.parent_uid=e.parent_uid AND j.parent_incarnation=e.parent_incarnation AND j.parent_request_id=e.parent_request_id
 WHERE e.id=NEW.intent_id AND c.id=NEW.child_id AND c.state IN ('pending','running') AND c.role='' AND c.delivery=''
 AND NOT EXISTS(SELECT 1 FROM ephemeral_child_failures WHERE intent_id=e.id)
 AND NOT EXISTS(SELECT 1 FROM actor_step_interruptions i WHERE i.swarm_id=e.swarm_id AND i.sequence=e.parent_sequence))
 BEGIN SELECT RAISE(ABORT,'registered executor failure scope conflicts'); END;
CREATE TRIGGER ephemeral_executor_failure_update_guard BEFORE UPDATE ON ephemeral_child_executor_failures BEGIN SELECT RAISE(ABORT,'registered executor failure is immutable'); END;
CREATE TRIGGER ephemeral_executor_failure_delete_guard BEFORE DELETE ON ephemeral_child_executor_failures BEGIN SELECT RAISE(ABORT,'registered executor failure is immutable'); END;
CREATE TRIGGER ephemeral_executor_failed_task_guard BEFORE UPDATE ON swarm_child_tasks WHEN EXISTS(SELECT 1 FROM ephemeral_child_executor_failures WHERE child_id=OLD.id) BEGIN SELECT RAISE(ABORT,'server-failed child cannot change actor report or transport'); END;
PRAGMA user_version=58;
COMMIT;
